import {defaults,demoData,parseCSV,backtest} from './engine.mjs';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const names={ma:'双均线策略',macd:'MACD 动量策略',rsi:'RSI 超卖反弹',boll:'布林带均值回归'};
const descriptions={ma:'短均线高于长均线时持仓，低于时离场。',macd:'DIF 高于信号线时持仓，低于时离场。',rsi:'RSI 低于买入阈值入场，高于卖出阈值离场。',boll:'收盘低于布林下轨入场，回到中轨时离场。'};
let data=demoData(), dataName='演示标的 · 合成日线', source='demo', strategy='ma', result, page=0, chartMode='nav', activeTab='trades', dirty=false, toastTimer;
let history=[];try{const h=JSON.parse(localStorage.getItem('qingheng-history')||'[]');if(Array.isArray(h))history=h.filter(x=>x&&x.config&&x.metrics&&x.period).slice(0,20);}catch{}
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(v,d=2)=>Number.isFinite(v)?v.toLocaleString('zh-CN',{minimumFractionDigits:d,maximumFractionDigits:d}):'—';
const pct=(v,signed=false)=>Number.isFinite(v)?(signed&&v>0?'+':'')+num(v*100)+'%':'—';
const cls=v=>!Number.isFinite(v)||v===0?'neutral':v>0?'positive':'negative';
function toast(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,3500);}
function config(){const o={...defaults,strategy};for(const [k,v]of new FormData($('#config')))o[k]=typeof defaults[k]==='number'?Number(v):v;return o;}
function setConfig(c){for(const[k,v]of Object.entries(c)){const el=$('#config').elements.namedItem(k);if(el)el.value=v;}selectStrategy(c.strategy||'ma');markDirty();}
function markDirty(){dirty=true;$('#config-status').textContent='参数已更改 · 点击运行回测更新结果';$('#config-status').className='config-status dirty';}
function selectStrategy(s){strategy=s;$$('[data-strategy]').forEach(b=>b.classList.toggle('active',b.dataset.strategy===s));$$('.strategy-params').forEach(p=>p.hidden=p.id!=='params-'+s);$('#strategy-desc').textContent=descriptions[s];markDirty();}
function showView(v){$$('.view').forEach(p=>p.hidden=p.id!=='view-'+v);$$('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===v));$('#breadcrumb').textContent={backtest:'策略回测',data:'行情数据',history:'本机回测记录',method:'回测规则'}[v];if(v==='history')renderHistory();if(v==='data')renderData();if(v==='backtest')requestAnimationFrame(renderChart);window.scrollTo({top:0,behavior:'instant'});}
function saveHistory(r){history.unshift({id:Date.now(),at:new Date().toISOString(),source,dataName,config:r.config,metrics:r.metrics,period:r.period});history=history.slice(0,20);try{localStorage.setItem('qingheng-history',JSON.stringify(history));}catch{toast('浏览器存储不可用，本次记录仅保留在当前页面。');}}
function run(save=true){try{const r=backtest(data,config());result={...r,dataName,source};page=0;dirty=false;$('#config-status').textContent='回测完成 · '+r.period.bars+' 个交易日';$('#config-status').className='config-status';$('#optimizer-results').innerHTML='';renderResults();if(save)saveHistory(r);return true;}catch(e){$('#config-status').textContent=e.message;$('#config-status').className='config-status error';toast(e.message);return false;}}
function renderResults(){const m=result.metrics;$('#result-title').textContent=names[result.config.strategy];$('#result-source').textContent=result.source==='demo'?'演示数据':'导入行情';$('#result-period').textContent=result.period.from+' — '+result.period.to;$('#chart-range').textContent=result.period.from+' 至 '+result.period.to;$('#chart-days').textContent=result.period.bars+' 个交易日';const list=[['累计收益',m.total,'期末资产 ¥ '+num(m.equity)],['年化收益',m.annual,'按 252 个交易日折算'],['最大回撤',m.maxdd,'从历史资产峰值计算'],['夏普比率',m.sharpe,'无风险利率设为 0']];$('#metrics').innerHTML=list.map(([label,value,detail],i)=>`<div class="metric"><div class="metric-label">${label}</div><div class="metric-value ${i<3?cls(value):'neutral'}">${i<3?(Number.isFinite(value)?`${value>0&&i<2?'+':''}${num(value*100)}<small>%</small>`:'—'):num(value)}</div><div class="metric-detail">${detail}</div></div>`).join('');$('#trade-count').textContent=result.trades.length;renderTrades();renderStats();renderChart();}
function renderTrades(){const rows=result.trades.slice().reverse(),pages=Math.max(1,Math.ceil(rows.length/8));page=Math.max(0,Math.min(page,pages-1));$('#trades-body').innerHTML=rows.length?rows.slice(page*8,page*8+8).map(t=>`<tr><td>${t.date}</td><td><span class="side-pill ${t.side==='买入'?'buy':'sell'}">${t.side}</span></td><td>${num(t.price,3)}</td><td>${num(t.quantity,0)}</td><td>${num(t.fee)}</td><td class="${cls(t.pnl)}">${t.pnl===null?'—':num(t.pnl)}</td><td>${t.reason}</td></tr>`).join(''):'<tr><td colspan="7" class="empty">该区间未产生可成交信号。可调整策略参数或回测区间。</td></tr>';$('#trade-summary').textContent=`共 ${rows.length} 笔成交 · ${result.closed.length} 笔已平仓`;$('#page-label').textContent=(page+1)+' / '+pages;$('#prev-page').disabled=page===0;$('#next-page').disabled=page>=pages-1;}
function renderStats(){const m=result.metrics;const rows=[['标的买入持有收益',pct(m.benchmark)],['策略相对标的收益',pct(m.excess,true)],['已平仓胜率',pct(m.winrate)],['已平仓盈亏比',num(m.profitFactor)],['年化波动率',pct(m.volatility)],['累计交易费用','¥ '+num(m.fees)],['因停牌 / 限价未成交',m.blocked+' 次尝试'],['期末持仓',num(m.quantity,0)+' 股'],['期末现金','¥ '+num(m.cash)],['已平仓交易',result.closed.length+' 笔']];$('#tab-stats').innerHTML='<div class="stats-grid">'+rows.map(([k,v])=>`<div class="stat-row"><span>${k}</span><strong>${v}</strong></div>`).join('')+'</div><p class="stats-note">盈亏比 = 已平仓盈利总额 ÷ 已平仓亏损总额的绝对值；没有亏损交易时不显示。期末持仓未强制卖出。止损止盈均在收盘确认后于次日执行。</p>';}
function renderChart(){if(!result||$('#view-backtest').hidden)return;const el=$('#chart'),w=Math.max(300,el.clientWidth-24),h=el.clientHeight,pad={l:53,r:14,t:16,b:33},pw=w-pad.l-pad.r,ph=h-pad.t-pad.b;const actual=result.curve;const first={date:'起始资金',nav:1,benchmark:1,drawdown:0,equity:result.config.capital};const points=[first,...actual];let sample=points.length<=650?points:points.filter((_,i)=>i%Math.ceil(points.length/650)===0||i===points.length-1);const field=chartMode==='nav'?'nav':'drawdown';const vals=points.flatMap(p=>chartMode==='nav'?[p.nav,p.benchmark]:[p.drawdown]);let lo=Math.min(...vals),hi=Math.max(...vals);const span=hi-lo||.1;lo-=span*.12;hi+=span*.12;if(chartMode==='drawdown')hi=0;const y=v=>pad.t+(hi-v)/(hi-lo)*ph;const x=i=>pad.l+i/(points.length-1)*pw;const path=(key)=>sample.map((p,i)=>`${i?'L':'M'}${x(points.indexOf(p)).toFixed(2)},${y(p[key]).toFixed(2)}`).join(' ');let svg=`<svg viewBox="0 0 ${w} ${h}" aria-hidden="true"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#0e887c" stop-opacity=".13"/><stop offset="100%" stop-color="#0e887c" stop-opacity=".005"/></linearGradient></defs>`;for(let i=0;i<5;i++){const v=lo+(hi-lo)*i/4,yy=y(v);svg+=`<line x1="${pad.l}" y1="${yy}" x2="${w-pad.r}" y2="${yy}" stroke="#eaf0f4" stroke-dasharray="3 4"/><text x="${pad.l-10}" y="${yy+4}" text-anchor="end">${chartMode==='nav'?num(v):num(v*100,1)+'%'}</text>`;}svg+=`<path d="${path(field)} L ${x(points.length-1)},${y(chartMode==='nav'?lo:0)} L ${x(0)},${y(chartMode==='nav'?lo:0)} Z" fill="url(#area)"/>`;if(chartMode==='nav')svg+=`<path d="${path('benchmark')}" fill="none" stroke="#a9b7c9" stroke-width="1.7" stroke-dasharray="5 3"/>`;svg+=`<path d="${path(field)}" fill="none" stroke="#0e887c" stroke-width="2.3" stroke-linejoin="round"/>`;for(let i=0;i<5;i++){const index=Math.round((points.length-2)*i/4)+1;svg+=`<text x="${x(index)}" y="${h-9}" text-anchor="${i===0?'start':i===4?'end':'middle'}">${points[index].date.slice(0,7)}</text>`;}svg+=`<line id="crosshair" y1="${pad.t}" y2="${h-pad.b}" stroke="#87bdb5" stroke-dasharray="4" visibility="hidden"/><rect x="${pad.l}" y="${pad.t}" width="${pw}" height="${ph}" fill="transparent"/></svg>`;el.innerHTML=svg;$('#benchmark-legend').hidden=chartMode!=='nav';$('#chart-unit').textContent=chartMode==='nav'?'起始净值 1.000':'相对历史峰值';$('#chart-subtitle').textContent=chartMode==='nav'?'归一化净值 · 已扣除交易成本':'历史回撤 · 从初始资金开始计算';el.onpointermove=e=>{const box=el.querySelector('svg').getBoundingClientRect(),local=(e.clientX-box.left)*w/box.width;if(local<pad.l||local>w-pad.r){hideTip();return;}const i=Math.max(0,Math.min(points.length-1,Math.round((local-pad.l)/pw*(points.length-1)))),r=points[i];const cross=$('#crosshair');cross.setAttribute('x1',x(i));cross.setAttribute('x2',x(i));cross.setAttribute('visibility','visible');$('#chart-tooltip').innerHTML=`<b>${r.date}</b><br>策略净值 ${num(r.nav,4)}<br>${chartMode==='nav'?'标的净值 '+num(r.benchmark,4):'回撤 '+pct(r.drawdown)}<br>资产 ¥ ${num(r.equity)}`;$('#chart-tooltip').hidden=false;};el.onpointerleave=hideTip;}
function hideTip(){$('#chart-tooltip').hidden=true;$('#crosshair')?.setAttribute('visibility','hidden');}
function renderData(){$('#data-title').textContent=dataName;$('#data-count').textContent=num(data.length,0)+' 条日线';$('#data-body').innerHTML=data.slice(-10).reverse().map(r=>`<tr><td>${r.date}</td><td>${num(r.open)}</td><td>${num(r.high)}</td><td>${num(r.low)}</td><td>${num(r.close)}</td><td>${num(r.volume,0)}</td></tr>`).join('');$('#data-range').textContent=`数据区间 ${data[0].date} — ${data.at(-1).date} · 显示最近 10 个交易日`;}
function renderHistory(){if(!history.length){$('#history-body').innerHTML='<div class="empty">暂无本机回测记录。运行一次回测后，参数与指标会出现在这里。</div>';return;}$('#history-body').innerHTML='<table><thead><tr><th>运行时间</th><th>标的 / 策略</th><th>累计收益</th><th>最大回撤</th><th>回测区间</th><th>操作</th></tr></thead><tbody>'+history.map((r,i)=>`<tr><td>${esc(new Date(r.at).toLocaleString('zh-CN',{hour12:false}))}</td><td>${esc(r.dataName)}<br>${esc(names[r.config.strategy]||r.config.strategy)}</td><td class="${cls(r.metrics.total)}">${pct(r.metrics.total,true)}</td><td class="negative">${pct(r.metrics.maxdd)}</td><td>${esc(r.period.from)} — ${esc(r.period.to)}</td><td><button class="load-params" data-history="${i}">载入参数</button></td></tr>`).join('')+'</tbody></table>';$$('[data-history]').forEach(b=>b.onclick=()=>{const h=history[Number(b.dataset.history)];setConfig(h.config);showView('backtest');toast('已载入参数；请确认当前标的后运行回测。');});}
function download(name,content,type='text/csv;charset=utf-8'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportReport(){if(!result)return;download('青衡回测报告-'+result.period.to+'.json',JSON.stringify({...result,exportedAt:new Date().toISOString(),methodology:{signal:'previous close -> next open',calendar:result.source==='demo'?'synthetic weekdays':'CSV rows',annualTradingDays:252,fees:'fixed over whole interval',dividends:false,benchmark:'raw close / first open, no fees',openPositions:'mark to close, not liquidated'},data},null,2),'application/json');toast('报告已导出，包含参数、行情、净值与成交记录。');}
$$('[data-view]').forEach(b=>b.onclick=()=>showView(b.dataset.view));$$('[data-strategy]').forEach(b=>b.onclick=()=>selectStrategy(b.dataset.strategy));$('#config').addEventListener('input',markDirty);$('#config').addEventListener('change',markDirty);$('#config').onsubmit=async e=>{e.preventDefault();$('#run').disabled=true;$('#run').textContent='正在回测…';await new Promise(r=>requestAnimationFrame(r));run();$('#run').disabled=false;$('#run').innerHTML='<span>▷</span> 运行回测';};
$$('[data-chart]').forEach(b=>b.onclick=()=>{chartMode=b.dataset.chart;$$('[data-chart]').forEach(x=>x.classList.toggle('active',x===b));renderChart();});$$('[data-tab]').forEach(b=>b.onclick=()=>{activeTab=b.dataset.tab;$$('[data-tab]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-selected',x===b);});$$('.tab-content').forEach(p=>p.hidden=p.id!=='tab-'+activeTab);$('#csv-export').hidden=activeTab!=='trades';});$('#prev-page').onclick=()=>{page--;renderTrades();};$('#next-page').onclick=()=>{page++;renderTrades();};$('#export').onclick=exportReport;
$('#csv-export').onclick=()=>{const csv='date,side,price,quantity,amount,fee,realized_pnl,reason\n'+result.trades.map(t=>[t.date,t.side,t.price.toFixed(4),t.quantity,t.amount.toFixed(2),t.fee.toFixed(2),t.pnl===null?'':t.pnl.toFixed(2),t.reason].join(',')).join('\n');download('青衡交易明细.csv','\uFEFF'+csv);};
$('#template').onclick=()=>{const rows=demoData().slice(0,180);download('行情格式模板-合成数据.csv','date,open,high,low,close,volume,prev_close\n'+rows.map(r=>[r.date,r.open,r.high,r.low,r.close,r.volume,r.prev_close].join(',')).join('\n'));toast('模板包含合成示例数据，请替换为实际历史行情。');};
let importedData, importedName;
$('#file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2*1024*1024)throw Error('文件超过 2 MB。');const bytes=await f.arrayBuffer();let t;try{t=new TextDecoder('utf-8',{fatal:true}).decode(bytes);}catch{throw Error('文件必须为 UTF-8 编码，请重新保存 CSV。');}const parsed=parseCSV(t);importedData=parsed;importedName=f.name.replace(/\.csv$/i,'');data=parsed;dataName=importedName;source='import';let opt=$('#dataset option[value="import"]');if(!opt){opt=document.createElement('option');opt.value='import';$('#dataset').append(opt);}opt.textContent=importedName+' · CSV';$('#dataset').value='import';$('#config').elements.from.value=data[Math.min(Math.max(35,config().slow),data.length-2)].date;$('#config').elements.to.value=data.at(-1).date;$('#import-status').textContent='已导入 '+num(data.length,0)+' 条日线。回到策略回测即可运行。';updateSource();renderData();markDirty();toast('行情导入成功，已切换至该标的。');}catch(err){$('#import-status').textContent=err.message;toast(err.message);}finally{e.target.value='';}};
function updateSource(){$('#source-notice').textContent=source==='demo'?'当前为合成演示行情，仅用于体验回测流程。研究真实股票请先导入历史日线。':'当前标的：'+dataName+'。已在本机载入 '+data.length+' 条日线；结果面板需运行回测后更新。';}
$('#dataset').onchange=()=>{source=$('#dataset').value;if(source==='demo'){data=demoData();dataName='演示标的 · 合成日线';$('#config').elements.from.value=defaults.from;$('#config').elements.to.value=defaults.to;}else{data=importedData;dataName=importedName;$('#config').elements.from.value=data[Math.min(Math.max(35,config().slow),data.length-2)].date;$('#config').elements.to.value=data.at(-1).date;}updateSource();markDirty();};
$('#optimize').onclick=async()=>{const btn=$('#optimize');btn.disabled=true;btn.textContent='正在比较…';await new Promise(r=>requestAnimationFrame(r));try{const c=config(),runs=[];for(const fast of[5,10,20])for(const slow of[30,60,90]){try{runs.push(backtest(data,{...c,strategy:'ma',fast,slow}));}catch(e){runs.push({config:{fast,slow},error:e.message});}}const ok=runs.filter(r=>!r.error).sort((a,b)=>b.metrics.total-a.metrics.total),bad=runs.filter(r=>r.error);$('#optimizer-results').innerHTML='<div class="table-wrap"><table><thead><tr><th>均线 / 日</th><th>累计收益</th><th>最大回撤</th><th>夏普</th><th>操作</th></tr></thead><tbody>'+ok.map((r,i)=>`<tr><td>${r.config.fast} / ${r.config.slow}</td><td class="${cls(r.metrics.total)}">${pct(r.metrics.total,true)}</td><td class="negative">${pct(r.metrics.maxdd)}</td><td>${num(r.metrics.sharpe)}</td><td><button class="load-params" data-opt="${i}">使用参数</button></td></tr>`).join('')+bad.map(r=>`<tr><td>${r.config.fast} / ${r.config.slow}</td><td colspan="4">${esc(r.error)}</td></tr>`).join('')+'</tbody></table></div><p class="stats-note">按本区间累计收益排序。请使用独立时间区间验证，避免过度拟合。</p>';$$('[data-opt]').forEach(b=>b.onclick=()=>{setConfig(ok[Number(b.dataset.opt)].config);toast('已载入参数，点击运行回测更新主结果。');});}catch(e){toast(e.message);}finally{btn.disabled=false;btn.textContent='运行 9 组参数';}};
$('#clear-history').onclick=()=>{history=[];try{localStorage.removeItem('qingheng-history');}catch{}renderHistory();toast('本机回测记录已清空。');};let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(renderChart,100);});run(false);renderData();
